#!/bin/bash
# Rebuild the site and deploy to Cloudflare Pages via wrangler direct-upload.
# Cron target — picks up new journal entries and deploys to CF Pages.
#
# The built site/index.html is NOT committed to git: it is generated by
# build.py from experiments/temporal-lab/runtime/journals/ (local-only,
# gitignored runtime state), so a CI build from the repo would produce an
# empty site. Instead we build locally and push the built artifact straight
# to Cloudflare Pages. See site/DEPLOY.md.

set -e

REPO="/Users/jjoosshhmbpm1/DOX_ICE/altered-states"
LOG="/tmp/site-rebuild.log"
HASH_FILE="/tmp/altered-states-site.hash"
cd "$REPO"

echo "=== $(date) ===" >> "$LOG"

# 1. Rebuild the site from local journals + experiments.
python3 build.py >> "$LOG" 2>&1

# 2. Skip the deploy if the built output is byte-identical to the last one.
NEW_HASH=$(shasum site/index.html | awk '{print $1}')
if [ -f "$HASH_FILE" ] && [ "$(cat "$HASH_FILE")" = "$NEW_HASH" ]; then
    echo "No site changes to deploy" >> "$LOG"
    exit 0
fi

# 3. Deploy the built site directly to Cloudflare Pages (no git commit).
if wrangler pages deploy site --project-name altered-states --commit-dirty=true >> "$LOG" 2>&1; then
    echo "$NEW_HASH" > "$HASH_FILE"
    echo "Deployed to Cloudflare Pages" >> "$LOG"
else
    echo "Deploy failed" >> "$LOG"
    exit 1
fi
